// Контент страниц городов: плюсы/минусы, индикаторы сложности, лучшие места,
// шаги визы, FAQ, отзывы. Источник правды для блоков, не зависящих от prices/cities в БД.
// Виктория правит этот файл руками — он версионируется через git, без миграций БД.

export type PlaceType =
  | "cafe"
  | "restaurant"
  | "district"
  | "market"
  | "coworking"
  | "park"
  | "attraction";

export type CityContent = {
  pros: string[];
  cons: string[];
  difficulty_breakdown: {
    visa: number;
    language: number;
    prices: number;
    infrastructure: number;
    community: number;
  };
  best_places: Array<{
    name: string;
    type: PlaceType;
    description: string;
    // Фото места (Supabase Storage, публичный bucket "photos"). Опционально —
    // старые записи и места без найденного фото рендерятся без картинки.
    image_url?: string;
  }>;
  visa_steps: Array<{ title: string; description: string }>;
  faq: Array<{ question: string; answer: string }>;
  reviews: Array<{
    author: string;
    age?: number;
    profession?: string;
    moved_year: number;
    text: string;
  }>;
  // --- Расширенные блоки (опциональные, заполняются по городам постепенно) ---
  // #17: развёрнутое описание города 250-350 слов — SEO-«тело» страницы.
  intro_long?: string;
  // #13: районы для проживания — название, характер, аренда-ориентир, для кого.
  districts?: Array<{
    name: string;
    vibe: string;
    rent: string;
    for_whom: string;
  }>;
  // #14 + #16: работа и удалёнка — рынок труда, зарплаты, сферы, связь/интернет.
  work?: {
    summary: string;
    salary: string;
    sectors: string[];
    remote: string;
    internet: string;
  };
};

